function extractSections(text) {
  const lines = text.split('\n');
  const result = [];
  let current = {heading:'Informasi awal', text:''};
  const isHeading = (line) =>
    /^(?:BAB\s+(?:[IVXLCDM]+|\d+)\b.*|\d+(?:\.\d+){0,3}[.)]?\s+\S.{2,100})$/i.test(line);
  for (const original of lines) {
    const line = original.trim();
    if (isHeading(line)) {
      if (current.text.trim()) result.push({...current, text:current.text.trim()});
      current = {heading:line, text:line};
    } else {
      current.text += (current.text ? '\n' : '') + original;
