// DocuGuard AI - Validate Evidence & Build Result1 (AI Agent workflow)
// Mode: Run Once for All Items
// Status Gemini 'Terpenuhi' / 'Sebagian Terpenuhi' TIDAK diturunkan hanya
// karena evidence_quote gagal dicocokkan. Bukti tetap diberi flag unverified.
// Skor = penilaian awal AI; bukan verifikasi bukti maupun persetujuan final.

const base = $('Validate & Prepare Text1').first().json;
const sopRaw = $('Apply Agent Decisions1').first().json.sopRaw;
const templateRaw = $('Apply Agent Decisions1').first().json.templateRaw;
const errors = [];
const statusMap = { 'Terpenuhi':'fulfilled', 'Sebagian Terpenuhi':'partial', 'Tidak Ditemukan':'not_found', 'Tidak Berlaku':'na', 'Perlu Review':'needs_review' };
const severityMap = { 'Informasi':'information', 'Minor':'minor', 'Mayor':'major', 'Kritis':'critical' };
const txt = (v, fallback='') => typeof v === 'string' ? v.trim() : fallback;
const has = (obj,key) => Object.prototype.hasOwnProperty.call(obj,key);

function parseAI(response,label) {
  try {
    if (!response || response.error || response.body?.error || Number(response.statusCode || 0) >= 400) {
      throw new Error(JSON.stringify(response?.error || response?.body?.error || response?.message || 'Permintaan AI gagal'));
    }
    const choice = response.choices?.[0] || response.body?.choices?.[0];
    if (choice?.finish_reason === 'length') throw new Error('Output AI terpotong');
    const raw = choice?.message?.content;
    if (typeof raw !== 'string' || !raw.trim()) throw new Error('Output AI kosong');
    const clean = raw.trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'').trim();
    const result = JSON.parse(clean);
    if (!Array.isArray(result?.findings) || !result.findings.length) throw new Error('Findings kosong; tidak boleh dianggap skor 0%');
    for (const f of result.findings) {
      if (!f || !txt(f.requirement) || !has(statusMap, f.status)) {
        throw new Error('Format finding tidak cocok: requirement/status tidak valid');
      }
    }
    return result;
  } catch (e) {
    errors.push({node:label,detail:String(e.message).slice(0,350)});
    return null;
  }
}
const sop = parseAI(sopRaw,'SOP Compliance AI');
const template = parseAI(templateRaw,'Template Completeness AI');
if (!sop || !template) return [{ json: {
  ok:false, reviewId:base.reviewId, status:'AI_REVIEW_FAILED',
  initial_review_status:'AI_REVIEW_FAILED', approval_status:'PENDING', human_review_required:true,
  message:'Respons AI gagal/tidak lengkap. Tidak dihitung sebagai kepatuhan 0%.',errors,
  safeguards:{automatic_approval:false,human_review_required:true}
}}];

const reportText = String(base.reportText || '');
// Toleransi pada PENCARIAN kutipan, bukan bukti substantif: jangan mengarang kutipan baru.
function stripChars(s) { return String(s).normalize('NFKC').toLowerCase().replace(/[\u200b-\u200d\ufeff]/g,'').replace(/[“”„]/g,'"').replace(/[‘’]/g,"'"); }
function validateQuote(value) {
  if (typeof value !== 'string' || !value.trim()) return {valid:false,quote:null,validation:'NO_QUOTE'};
  const q = value.trim();
  if (reportText.includes(q)) return {valid:true,quote:q,validation:'VERIFIED_EXACT_QUOTE'};
  // Token-level matching tolerates whitespace and quote styling/case; returns actual report substring.
  const tokens = [...q.matchAll(/\S+/g)].map(m=>m[0]);
  if (!tokens.length) return {valid:false,quote:null,validation:'NO_QUOTE'};
  const tokenRegex = /\S+/g;
  const indexed = [...reportText.matchAll(tokenRegex)];
  const target = tokens.map(stripChars);
  for(let i=0;i+target.length<=indexed.length;i++) {
    let match=true;
    for(let j=0;j<target.length;j++) {
      if(stripChars(indexed[i+j][0])!==target[j]) {match=false;break;}
    }
    if(match) {
      const first=indexed[i].index, last=indexed[i+target.length-1];
      return {valid:true,quote:reportText.slice(first,last.index+last[0].length),validation:'VERIFIED_NORMALIZED_QUOTE'};
    }
  }
  // Fallback untuk tanda baca di batas kata akibat konversi DOCX.
  // Tidak digunakan jika ada token angka sehingga tidak mengubah bukti nominal.
  if (tokens.length >= 5 && !tokens.some(x => /\d/.test(x))) {
    const normProse = s => stripChars(s).replace(/^[^\p{L}\p{N}]+|[^\p{L}\p{N}]+$/gu,'');
    for (let i=0; i+tokens.length<=indexed.length; i++) {
      let match=true;
      for(let j=0; j<tokens.length; j++) {
        if(normProse(indexed[i+j][0])!==normProse(tokens[j])) { match=false; break; }
      }
      if(match){
        const first=indexed[i].index, last=indexed[i+tokens.length-1];
        return {valid:true,quote:reportText.slice(first,last.index+last[0].length),validation:'VERIFIED_NORMALIZED_QUOTE'};
      }
    }
  }
  return {valid:false,quote:null,validation:'QUOTE_NOT_FOUND'};
}
function processFindings(items, source) {
  return items.map((f,index)=>{
    const evidence=validateQuote(f.evidence_quote);
    let status=f.status;
    let explanation=txt(f.explanation);
    let recommendation=txt(f.recommendation);
    const requiresEvidence = status==='Terpenuhi' || status==='Sebagian Terpenuhi';
    // Jangan ubah keputusan substantif AI hanya karena kutipan tidak cocok.
    // Catat secara transparan bahwa bukti belum terverifikasi.
    // Ini adalah status penilaian awal AI, BUKAN kepatuhan yang sudah tervalidasi.
    if (requiresEvidence && !evidence.valid) {
      explanation = (explanation || 'Gemini menilai persyaratan ini sesuai.') +
        ' Catatan validasi: kutipan tidak ditemukan secara otomatis dalam teks hasil ekstraksi; ' +
        'status penilaian awal AI dipertahankan, tetapi bukti belum terverifikasi.';
      recommendation = (!recommendation || recommendation.toLowerCase() === 'tidak ada')
        ? 'Periksa hasil ekstraksi dan kutipan bukti untuk verifikasi.'
        : recommendation + ' Periksa juga hasil ekstraksi dan kutipan bukti untuk verifikasi.';
    }
    if (status==='Tidak Berlaku' && !explanation) {
      status='Perlu Review'; explanation='Alasan ketidakberlakuan tidak dijelaskan.';
      recommendation='Pastikan kondisi persyaratan memang tidak berlaku.';
    }
    if (status==='Perlu Review') {
      if(!explanation) explanation='Ada ketidakpastian material yang belum diselesaikan.';
      if(!recommendation || recommendation.toLowerCase()==='tidak ada') recommendation='Verifikasi bukti atau ketidakpastian spesifik yang disebutkan.';
    }
    if (status==='Sebagian Terpenuhi' || status==='Tidak Ditemukan') {
      if(!recommendation || recommendation.toLowerCase()==='tidak ada') recommendation='Lengkapi unsur wajib yang belum tersedia.';
    }
    if ((status==='Terpenuhi'||status==='Tidak Berlaku') && !recommendation) recommendation='Tidak ada';
    const severity=has(severityMap,f.severity) ? f.severity : 'Informasi';
    // Flag lama true pada temuan definitif tidak memaksa eskalasi seluruh review.
    const needsHuman = status==='Perlu Review' || severity==='Kritis';
    return {
      id:(source==='SOP'?'SOP-':'TPL-')+String(index+1).padStart(2,'0'), source,
      requirement_ref:txt(f.requirement_ref), requirement:txt(f.requirement), status,
      evidence_quote:evidence.valid?evidence.quote:null, evidence_validation:evidence.validation,
      // Membedakan keputusan AI dari verifikasi bukti.
      evidence_verified:evidence.valid,
      evidence_followup_required:requiresEvidence && !evidence.valid,
      explanation,recommendation,severity,needs_human_review:needsHuman
    };
  });
}
const sopFind=processFindings(sop.findings,'SOP');
const templateFind=processFindings(template.findings,'TEMPLATE');
const all=[...sopFind,...templateFind];
const unverifiedEvidenceFindings=all.filter(f=>
  (f.status==='Terpenuhi'||f.status==='Sebagian Terpenuhi') &&
  !['VERIFIED_EXACT_QUOTE','VERIFIED_NORMALIZED_QUOTE'].includes(f.evidence_validation)
);
const hasUncertainty=all.some(f=>f.needs_human_review);
const hasDeficiency=all.some(f=>f.status==='Sebagian Terpenuhi'||f.status==='Tidak Ditemukan');
const allFulfilled=all.every(f=>f.status==='Terpenuhi'||f.status==='Tidak Berlaku');
const initialReviewStatus=hasUncertainty?'NEEDS_HUMAN_REVIEW':hasDeficiency?'NEEDS_REVISION':allFulfilled?'PASSED_INITIAL_REVIEW':'NEEDS_HUMAN_REVIEW';
const approvalStatus='PENDING';
const findingCounts=Object.fromEntries(Object.keys(severityMap).map(k=>[k,all.filter(f=>f.severity===k).length]));
const statusCounts=Object.fromEntries(Object.keys(statusMap).map(k=>[k,all.filter(f=>f.status===k).length]));
const evidenceCounts={
  exact:all.filter(f=>f.evidence_validation==='VERIFIED_EXACT_QUOTE').length,
  normalized:all.filter(f=>f.evidence_validation==='VERIFIED_NORMALIZED_QUOTE').length,
  not_found:all.filter(f=>f.evidence_validation==='QUOTE_NOT_FOUND').length,
  no_quote:all.filter(f=>f.evidence_validation==='NO_QUOTE').length
};
const summary=[txt(sop.summary),txt(template.summary)].filter(Boolean).join(' ');
function frontendFinding(f,index) { return {
  id:'F-'+String(index+1).padStart(2,'0'),title:f.requirement,summary:f.explanation,
  status:statusMap[f.status],severity:severityMap[f.severity],
  sopRef:f.source==='SOP'?f.requirement_ref:'',
  templateSection:f.source==='TEMPLATE'?f.requirement_ref:'',
  requirement:{ref:f.requirement_ref,text:f.requirement},
  evidence:f.evidence_quote?[{id:'E-'+String(index+1),docRole:'Laporan',docName:base.reportName,excerpt:f.evidence_quote,location:null}]:[],
  evidence_validation:f.evidence_validation,
  evidence_verified:f.evidence_verified,
  evidence_followup_required:f.evidence_followup_required,
  explanation:f.explanation,
  recommendation:f.recommendation,needs_human_review:f.needs_human_review
}; }
const frontendReview={
  id:base.reviewId,title:base.reportName,version:base.version,domain:base.documentDomain||'Dokumen Umum',
  checkedAt:new Date().toISOString(),status:initialReviewStatus,initial_review_status:initialReviewStatus,
  approval_status:approvalStatus,human_review_required:hasUncertainty,
  evidence_verification_pending:unverifiedEvidenceFindings.length>0,
  summary,docs:[
    {role:'SOP',name:base.sopName,meta:'Referensi SOP'},
    {role:'Template',name:base.templateName,meta:'Referensi format'},
    {role:'Laporan',name:base.reportName,meta:'Dokumen diperiksa'}
  ],findings:all.map(frontendFinding),
  sopAssessment:sopFind.map(f=>({ref:f.requirement_ref,label:f.requirement,status:statusMap[f.status]})),
  templateAssessment:templateFind.map(f=>({ref:f.requirement_ref,label:f.requirement,status:statusMap[f.status]})),
  recommendations:all.map((f,index)=>({f,index})).filter(({f})=>f.status!=='Terpenuhi'&&f.status!=='Tidak Berlaku'&&f.recommendation)
    .map(({f,index})=>({id:'R-'+String(index+1),findingId:'F-'+String(index+1).padStart(2,'0'),text:f.recommendation,detail:f.explanation}))
};
function score(items) {
  const applicable=items.filter(f=>f.status!=='Tidak Berlaku');
  const reviewed=applicable.filter(f=>f.status!=='Perlu Review');
  return {
    // Persentase ini berdasarkan penilaian awal Gemini, bukan persetujuan audit final.
    percentage:reviewed.length ? Math.round(100*reviewed.reduce((s,f)=>s+(f.status==='Terpenuhi'?1:f.status==='Sebagian Terpenuhi'?0.5:0),0)/reviewed.length) : null,
    score_basis:'penilaian_awal_ai',
    evaluated:reviewed.length, pending:applicable.length-reviewed.length, total:applicable.length,
    unverified_evidence:applicable.filter(f=>(f.status==='Terpenuhi'||f.status==='Sebagian Terpenuhi') &&
      !['VERIFIED_EXACT_QUOTE','VERIFIED_NORMALIZED_QUOTE'].includes(f.evidence_validation)).length,
    final:reviewed.length===applicable.length && applicable.every(f=>
      (f.status!=='Terpenuhi' && f.status!=='Sebagian Terpenuhi') ||
      ['VERIFIED_EXACT_QUOTE','VERIFIED_NORMALIZED_QUOTE'].includes(f.evidence_validation))
  };
}
return [{json:{
  ok:true, reviewId:base.reviewId,reportType:base.reportType,reportName:base.reportName,
  status:initialReviewStatus,initial_review_status:initialReviewStatus,
  approval_status:approvalStatus,human_review_required:hasUncertainty,findings_need_human_review:hasUncertainty,
  summary,scope:base.scope,sop_findings:sopFind,template_findings:templateFind,
