    note:'Skor mencerminkan penilaian awal AI; bukti yang belum cocok belum terverifikasi.'
  },
  sop_score_diagnostics:score(sopFind),template_score_diagnostics:score(templateFind),
  referenceSnapshot:base.referenceSnapshot,agent_diagnostics:$('Apply Agent Decisions1').first().json.agent_diagnostics,frontend_review:frontendReview,
  safeguards:{automatic_approval:false,evidence_quotes_checked_against_report_text:true,
    whitespace_normalization_enabled:true,semantic_evidence_sufficiency_automatically_verified:false,
    full_sop_coverage_independently_verified:false,full_template_coverage_independently_verified:false,
    scope_limited_to_supplied_or_extracted_criteria:true,
