// Input tool: JSON string {"keyword":"istilah", "context":160}.
// Baca dokumen dari node validasi, bukan dari klaim agent.
let input;
try {input=typeof query==='string'?JSON.parse(query):query;} catch(e) {input={keyword:String(query||'')};}
const keyword=String(input.keyword||input.query||'').trim();
if(!keyword || keyword.length>150) return JSON.stringify({error:'keyword wajib 1-150 karakter'});
let report='';
try {report=String($('Validate & Prepare Text1').first().json.reportText||'');}
catch(e){return JSON.stringify({error:'Sumber laporan tidak dapat diakses oleh tool. Periksa konfigurasi Code Tool.',detail:e.message});}
const lower=report.toLowerCase(),term=keyword.toLowerCase();
const radius=Math.min(400,Math.max(80,Number(input.context)||180));
const hits=[];
let at=0;
while(hits.length<12){
 const i=lower.indexOf(term,at);if(i<0) break;
 const start=Math.max(0,i-radius),end=Math.min(report.length,i+keyword.length+radius);
 hits.push({start,end,excerpt:report.slice(start,end)});at=i+Math.max(1,term.length);
}
return JSON.stringify({keyword,total_hits_returned:hits.length,hits,report_length:report.length,truncated_at_12_hits:hits.length===12});

// Input: JSON string {"quote":"kutipan yang akan diuji"}.
// Hanya mengembalikan substring yang BENAR-BENAR berasal dari reportText.
let input;
try {input=typeof query==='string'?JSON.parse(query):query;} catch(e) {input={quote:String(query||'')};}
const q=String(input.quote||'').trim();
if(!q||q.length>2500) return JSON.stringify({valid:false,error:'quote harus 1-2500 karakter'});
let report='';
try {report=String($('Validate & Prepare Text1').first().json.reportText||'');}
catch(e){return JSON.stringify({valid:false,error:'Sumber laporan tidak tersedia untuk tool',detail:e.message});}
const exact=report.indexOf(q);
if(exact>=0) return JSON.stringify({valid:true,method:'exact',start:exact,quote:report.slice(exact,exact+q.length)});
const canonical=(s)=>String(s).normalize('NFKC').toLowerCase().replace(/[\u200b-\u200d\ufeff]/g,'').replace(/[“”„]/g,'"').replace(/[‘’]/g,"'");
const target=q.match(/\S+/g)||[];
const found=[...report.matchAll(/\S+/g)];
for(let i=0;i+target.length<=found.length;i++){
 let okay=true;
 for(let j=0;j<target.length;j++)if(canonical(found[i+j][0])!==canonical(target[j])){okay=false;break;}
 if(okay){const start=found[i].index;const tail=found[i+target.length-1];return JSON.stringify({valid:true,method:'normalized',start,quote:report.slice(start,tail.index+tail[0].length)});}
}
return JSON.stringify({valid:false,method:'not_found',quote:null});

// Input JSON: {"operation":"sum|difference|percentage","numbers":[100,20],"reported":120}
let input;try{input=typeof query==='string'?JSON.parse(query):query;}catch(e){return JSON.stringify({error:'Input harus JSON'});}
const numbers=Array.isArray(input.numbers)?input.numbers:[];
if(numbers.length<2||numbers.length>50||numbers.some(n=>typeof n!=='number'||!Number.isFinite(n)))return JSON.stringify({error:'numbers harus array 2-50 bilangan valid'});
let value; const op=String(input.operation||'').toLowerCase();
if(op==='sum')value=numbers.reduce((s,n)=>s+n,0);
else if(op==='difference')value=numbers.slice(1).reduce((s,n)=>s-n,numbers[0]);
else if(op==='percentage'){if(numbers[1]===0)return JSON.stringify({error:'Pembagi nol'});value=numbers[0]/numbers[1]*100;}
else return JSON.stringify({error:'operation hanya sum/difference/percentage'});
const reported=typeof input.reported==='number'&&Number.isFinite(input.reported)?input.reported:null;
return JSON.stringify({operation:op,numbers,calculated:value,reported,delta:reported===null?null:value-reported,match:reported===null?null:Math.abs(value-reported)<0.005});

// Tahap awal: hasil SOP dan template dari dua pemeriksa Gemini.
// Hanya temuan yang belum pasti / kutipannya bermasalah dikirim ke AI Agent.
const base = $('Validate & Prepare Text1').first().json;
function parseRaw(raw, label) {
  if (!raw || raw.error || raw.body?.error || Number(raw.statusCode || 0) >= 400) {
    return {error:label+' gagal memanggil Gemini', findings:[]};
  }
  const choice = raw.choices?.[0] || raw.body?.choices?.[0];
  if (choice?.finish_reason === 'length') return {error:label+' terpotong',findings:[]};
  const content = choice?.message?.content;
  if (typeof content !== 'string') return {error:label+' tidak menghasilkan teks',findings:[]};
  try {
    const obj = JSON.parse(content.trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'').trim());
    if (!Array.isArray(obj.findings)) throw new Error('findings bukan array');
    return {data:obj,findings:obj.findings};
  } catch(e) {return {error:label+' JSON tidak valid: '+e.message,findings:[]};}
}
const sopParsed=parseRaw($('SOP Compliance AI1').first().json,'SOP');
const templateParsed=parseRaw($('Template Completeness AI1').first().json,'Template');
const report=String(base.reportText||'');
const suspects=[];
for(const [source, parsed] of [['SOP',sopParsed],['TEMPLATE',templateParsed]]){
  for(let index=0;index<parsed.findings.length;index++){
    const f=parsed.findings[index];
    const quote=typeof f.evidence_quote==='string'?f.evidence_quote.trim():'';
    const missing=(f.status==='Terpenuhi'||f.status==='Sebagian Terpenuhi')&&(!quote||!report.includes(quote));
    if(f.status==='Perlu Review'||missing||f.status==='Sebagian Terpenuhi'||f.status==='Tidak Ditemukan'){suspects.push({source,index,requirement_ref:f.requirement_ref,requirement:f.requirement,status_awal:f.status,evidence_quote:f.evidence_quote,explanation:f.explanation,reason:f.status==='Perlu Review'?'ketidakpastian AI':missing?'kutipan perlu dicari ulang':'pemeriksaan ulang kekurangan material'});}
  }
}
const prompt={
  tugas:'Investigasi lanjutan temuan DocuGuard. Ini BUKAN audit ulang keseluruhan.',
  laporan:base.reportName,
  jenis_laporan:base.reportType,
  petunjuk_tahap_laporan:(String(base.reportText||'').match(/(?:status\s*(?:laporan|dokumen)|tahap\s*(?:laporan|dokumen))\s*[:=]\s*[^\n]{1,100}/i)||[])[0]||'Tahap tidak diketahui; investigasi teks bila diperlukan',
  sop_referensi:base.sopCriteriaText,
  template_referensi:base.templateCriteriaText,
  temuan_perlu_investigasi:suspects,
  instruksi:'Investigasi BERBASIS BUKTI, bukan memaksakan 100%. Gunakan Cari_Bukti_Laporan untuk bukti yang terlewat, Verifikasi_Kutipan untuk kutipan asli sebelum menaikkan pemenuhan, dan Cek_Aritmetika untuk selisih. Jika rekap ada tapi hitungannya salah, SARANKAN Sebagian Terpenuhi, bukan Tidak Ditemukan. Jika dokumen DRAF menulis Belum diperiksa / menunggu persetujuan dan SOP hanya mewajibkan persetujuan sesuai status, jangan menuntut persetujuan final: cek identitas dan status proses yang diwajibkan, lalu boleh Terpenuhi. Namun jika final/terbit butuh persetujuan, catat kekurangan. Jangan menilai sama dua nominal yang selisihnya benar-benar terjadi, jangan anggap typo sebagai kekurangan. Output JSON {"decisions":[{"source":"SOP","index":0,"status":"Terpenuhi","evidence_quote":"kutipan asli","explanation":"...","recommendation":"Tidak ada","severity":"Informasi","needs_human_review":false}],"summary":"..."}. Bila tidak ada perubahan yang terbukti: {"decisions":[],"summary":"Tidak ada perubahan"}. Indeks 0-based dari array awal dan tidak boleh menciptakan temuan baru.'
};
return [{json:{reviewId:base.reviewId,agentPrompt:JSON.stringify(prompt),needsAgent:suspects.length>0,suspectCount:suspects.length,preparationErrors:[sopParsed.error,templateParsed.error].filter(Boolean)}}];

// Terapkan hasil AI Agent sebagai USULAN dan verifikasi ulang secara deterministik.
// Jika Agent gagal / JSON salah, hasil awal tetap dipakai (graceful fallback).
const base=$('Validate & Prepare Text1').first().json;
const original=$('Prepare Agent Investigation1').first().json;
const sopRaw=$('SOP Compliance AI1').first().json;
const templateRaw=$('Template Completeness AI1').first().json;
const diagnostics={agent_used:original.needsAgent,suspect_count:original.suspectCount,applied:0,rejected:[],agent_error:null};
function decode(raw) {
 const choice=raw.choices?.[0]||raw.body?.choices?.[0];
 const str=choice?.message?.content;
 if(typeof str!=='string')return null;
 try{return JSON.parse(str.trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'').trim());}
 catch(e){return null;}
}
function encode(data){return {choices:[{message:{content:JSON.stringify(data)},finish_reason:'stop'}]};}
const sop=decode(sopRaw);const tpl=decode(templateRaw);
if(!sop||!tpl) return [{json:{sopRaw,templateRaw,agent_diagnostics:{...diagnostics,agent_error:'Output awal SOP/Template tidak dapat diparsing; validasi berikutnya akan menangani kegagalan.'}}}];
function matchQuote(raw){
 const text=String(base.reportText||'');
 if(typeof raw!=='string'||!raw.trim())return null;
 const q=raw.trim();if(text.includes(q))return q;
 const norm=s=>String(s).normalize('NFKC').toLowerCase().replace(/[\u200b-\u200d\ufeff]/g,'').replace(/[“”„]/g,'"').replace(/[‘’]/g,"'");
 const normProse=s=>norm(s).replace(/^[^\p{L}\p{N}]+|[^\p{L}\p{N}]+$/gu,'');
 const words=q.match(/\S+/g)||[];const tokens=[...text.matchAll(/\S+/g)];
 for(let i=0;i+words.length<=tokens.length;i++){
  let okay=true;for(let j=0;j<words.length;j++)if(norm(words[j])!==norm(tokens[i+j][0])){okay=false;break;}
  if(okay){const last=tokens[i+words.length-1];return text.slice(tokens[i].index,last.index+last[0].length);}
 }
 // Perbedaan tanda baca di batas kata sering muncul dari ekstraksi DOCX.
 // Jangan terapkan aturan ini pada kutipan numerik, agar nilai keuangan tetap utuh.
 const prose=words.length>=5 && !words.some(x=>/\d/.test(x));
 if(prose){
  for(let i=0;i+words.length<=tokens.length;i++){
   let okay=true;
   for(let j=0;j<words.length;j++)if(normProse(words[j])!==normProse(tokens[i+j][0])){okay=false;break;}
   if(okay){const tail=tokens[i+words.length-1];return text.slice(tokens[i].index,tail.index+tail[0].length);}
  }
 }
 return null;
}
let agentOutput='';
try{const inp=$input.first().json;agentOutput=inp.output||inp.text||'';}catch(e){}
let result=null;
if(typeof agentOutput==='string'){
 try{result=JSON.parse(agentOutput.trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'').trim());}
 catch(e){diagnostics.agent_error='AI Agent tidak mengeluarkan JSON decisions valid: '+e.message;}
}else if(agentOutput&&typeof agentOutput==='object')result=agentOutput;
if(!result && original.needsAgent) diagnostics.agent_error=diagnostics.agent_error||'AI Agent tidak tersedia, hasil awal digunakan.';
const decisions=Array.isArray(result?.decisions)?result.decisions:[];
const validStatus=new Set(['Terpenuhi','Sebagian Terpenuhi','Tidak Ditemukan','Tidak Berlaku','Perlu Review']);
const validSeverity=new Set(['Informasi','Minor','Mayor','Kritis']);
for(const d of decisions){
 const target=d.source==='SOP'?sop:d.source==='TEMPLATE'?tpl:null;
 const idx=d.index;
 if(!target||!Number.isInteger(idx)||idx<0||idx>=target.findings.length||!validStatus.has(d.status)){
  diagnostics.rejected.push('Target/status tidak valid: '+JSON.stringify({source:d.source,index:idx,status:d.status}));continue;
 }
 const f=target.findings[idx];
 const previousQuote=matchQuote(f.evidence_quote);
 const eligible=f.status==='Perlu Review'||f.status==='Sebagian Terpenuhi'||f.status==='Tidak Ditemukan'||(f.status==='Terpenuhi'&&!previousQuote);
 if(!eligible){diagnostics.rejected.push(d.source+':'+idx+' bukan temuan investigasi');continue;}
 const fixedQuote=matchQuote(d.evidence_quote);
 if((d.status==='Terpenuhi'||d.status==='Sebagian Terpenuhi')&&!fixedQuote){
  diagnostics.rejected.push(d.source+':'+idx+' status pemenuhan baru ditolak karena kutipan tidak ditemukan');continue;
 }
 // Klasifikasi Tidak Berlaku hanya bisa digunakan bila ada penjelasan spesifik.
 if(d.status==='Tidak Berlaku'&&!(typeof d.explanation==='string'&&d.explanation.trim())){
  diagnostics.rejected.push(d.source+':'+idx+' Tidak Berlaku tanpa alasan');continue;
 }
 target.findings[idx]={...f,
  status:d.status,
  evidence_quote:fixedQuote,
  explanation:typeof d.explanation==='string'&&d.explanation.trim()?d.explanation:f.explanation,
  recommendation:typeof d.recommendation==='string'&&d.recommendation.trim()?d.recommendation:f.recommendation,
  severity:validSeverity.has(d.severity)?d.severity:f.severity,
  needs_human_review:d.status==='Perlu Review'||d.severity==='Kritis'
 };
 diagnostics.applied++;
}
return [{json:{sopRaw:encode(sop),templateRaw:encode(tpl),agent_diagnostics:diagnostics}}];
